// Package store owns the SQLite file and every write the service performs.
package store

import (
	"database/sql"
	"errors"
	"fmt"

	_ "modernc.org/sqlite"
)

// Store wraps the SQLite handle so callers never touch database/sql directly.
type Store struct {
	db *sql.DB
}

// Stream is the registered windowing configuration and progress of one data stream.
type Stream struct {
	StreamID               string
	WindowType             string
	WindowSizeSeconds      float64
	AllowedLatenessSeconds float64
	Watermark              int64
}

// Business errors the API layer translates into the published error codes.
var (
	ErrStreamExists        = errors.New("store: stream already exists")
	ErrStreamNotFound      = errors.New("store: stream not found")
	ErrWatermarkOutOfOrder = errors.New("store: watermark moves backwards")
)

// Open prepares the database file and the schema this service needs.
func Open(path string) (*Store, error) {
	db, err := sql.Open("sqlite", path)
	if err != nil {
		return nil, fmt.Errorf("open sqlite: %w", err)
	}
	// A single connection serializes transactions, so a watermark compare-and-write can
	// never interleave with another writer on the same file.
	db.SetMaxOpenConns(1)
	if _, err := db.Exec("PRAGMA journal_mode=WAL"); err != nil {
		db.Close()
		return nil, fmt.Errorf("enable wal: %w", err)
	}
	if _, err := db.Exec(schema); err != nil {
		db.Close()
		return nil, fmt.Errorf("apply schema: %w", err)
	}
	return &Store{db: db}, nil
}
```

